SELECT * FROM stock_watch_analysis_demand
WHERE active_coalesce_key=#{activeCoalesceKey}
LIMIT 1

SELECT * FROM stock_watch_analysis_demand
WHERE status IN ('PENDING','CLAIMED')
  AND not_before <= #{now} AND deadline_at > #{now}
  AND (status!='CLAIMED' OR lease_until <= #{now})
ORDER BY priority DESC, id ASC LIMIT #{limit}
